// Auto-assign pool. Includes 'owner'/'gestor' (management roles that handle
// conversations) — without 'owner' a solo account (only the creator, now
// role='owner' since migration 000149) had zero assignable users and every
// inbound conversation auto-assigned to nobody.
func (q *Queries) GetActiveAttendants(ctx context.Context, accountID string) ([]string, error) {
	rows, err := q.db.Query(ctx, getActiveAttendants, accountID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

